// spec: specs/gifts.md (раздел 6.1)
// seed: tests/seed.new02.spec.ts
// ОКРУЖЕНИЕ: у new02 на 19.11 нет чата «בדיקה כללי» — вместо него «QA П1 0010» (ж, мэтч new01↔new02). Вход в подарок — через меню «פעולות על הצ'אט».
import { test, expect } from '@playwright/test';
import path from 'path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/new02.json'), colorScheme: 'dark' });

const PARTNER = 'QA П1 0010';

test.describe('Раунд 13: подарки (#47a8b8 #dc2c6f #676952 #e0de78)', () => {
  test('Экран «שליחת מתנה» для «דובי פרחים»: превью, счётчик 140, чип, кнопка ₪7.90 @iphone @prod-safe', async ({ page }) => {
    const sendGiftRequests: string[] = [];
    page.on('request', (r) => {
      if (/send_gift|payment|purchase/i.test(r.url())) sendGiftRequests.push(r.url());
    });

    // 1. `/matches` → «בדיקה כללי» → 🎁 → «דובי פרחים».
    await page.goto('/matches');
    await page.getByRole('button', { name: new RegExp(`^${PARTNER}`) }).click();
    await page.waitForURL(/\/chat\//);
    await page.getByRole('button', { name: 'פעולות על הצ\'אט' }).click();
    await page.getByRole('button', { name: new RegExp(`שליחת מתנה ל־.*${PARTNER}`) }).click();
    await page.getByRole('button', { name: /^דובי פרחים · ₪/ }).click();

    // 2. Посмотреть экран; нажать чип «קפה עליי?».
    await expect(page.getByRole('heading', { name: 'שליחת מתנה', level: 1 })).toBeVisible();
    await expect(page.getByText(new RegExp(`כך ${PARTNER} (תראה|יראה) את זה`))).toBeVisible();
    await expect(page.getByText('QA П2 0011 שלח לך מתנה')).toBeVisible();
    await expect(page.getByText('מתנה מ־')).toBeVisible();
    await expect(page.getByText('QA П2 0011', { exact: true })).toBeVisible();
    await expect(page.getByText('דובי פרחים', { exact: true })).toBeVisible();

    const field = page.getByRole('textbox', { name: 'הוסף הודעה (לא חובה)' });
    await expect(field).toBeVisible();
    await expect(page.getByText('0/140', { exact: true })).toBeVisible();
    await expect(page.getByText(/תקבל התראה, וההודעה שלך תופיע אצלה ראשונה/)).toBeVisible();
    await expect(page.getByText(/מתנה וירטואלית: מופיעה באפליקציה בלבד, בלי פריט פיזי/)).toBeVisible();
    await expect(page.getByRole('button', { name: 'שליחת מתנה • ₪7.90' })).toBeVisible();

    await page.getByRole('button', { name: 'קפה עליי?' }).click();
    await expect(field).toHaveValue('קפה עליי?');
    await expect(page.getByText(`${'קפה עליי?'.length}/140`, { exact: true })).toBeVisible();

    // 3. Очистить поле и ввести текст из 150 символов.
    await field.clear();
    await field.fill('אבגדהוזחטי '.repeat(14).slice(0, 150));
    await expect(page.getByText('140/140', { exact: true })).toBeVisible();
    await expect(field).toHaveValue(/^[\s\S]{140}$/);

    // Кнопка с ценой до подтверждения; send_gift и оплата не вызывались.
    await expect(page.getByRole('button', { name: 'שליחת מתנה • ₪7.90' })).toBeVisible();
    expect(sendGiftRequests, 'send_gift/оплата не вызывались').toEqual([]);
  });
});
